package cn.yueji.balance;

import org.junit.Test;
import org.json.*;
import java.math.*;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

public class V470RulesTest {
    @Test public void elapsedUsesFullYearsAndRemainingDays(){
        assertEquals("2年94日",WatchAnalytics.elapsed(LocalDate.of(2024,7,23),LocalDate.of(2026,10,25)));
        assertEquals("94天",WatchAnalytics.elapsed(LocalDate.of(2026,7,23),LocalDate.of(2026,10,25)));
        assertEquals("1年0日",WatchAnalytics.elapsed(LocalDate.of(2025,10,25),LocalDate.of(2026,10,25)));
        assertEquals("0天",WatchAnalytics.elapsed(LocalDate.of(2026,10,25),LocalDate.of(2026,10,25)));
        assertEquals("待获取",WatchAnalytics.elapsed(LocalDate.of(2027,1,1),LocalDate.of(2026,10,25)));
        assertEquals("1年1日",WatchAnalytics.elapsed(LocalDate.of(2024,2,29),LocalDate.of(2025,3,1)));
    }
    Ledger.Data accounts(){return new AccountCashTest().data();}
    Ledger.Fund fund(Ledger.Data d){Ledger.Fund f=new Ledger.Fund();f.id=100;f.code="000001";f.name="测试6个月持有基金A";d.funds.add(f);return f;}
    Ledger.FundBuy buy(Ledger.Fund f,boolean linked){Ledger.FundBuy b=new Ledger.FundBuy();b.id=101;b.at=LocalDateTime.parse("2026-09-05T10:00");b.amount=20000;b.buyAccountLinked=linked;b.buyAccountId=linked?1:0;b.tradeDate=b.at.toLocalDate();b.confirmDate=b.tradeDate.plusDays(1);f.buys.add(b);return b;}
    @Test public void buyAndSaleOnDifferentAccountsAreCashNotExpense(){Ledger.Data d=accounts();Ledger.FundBuy b=buy(fund(d),true);b.saleDate=LocalDate.of(2026,9,10);b.saleAt=b.saleDate.atTime(17,0);b.saleAmount=22000;b.saleAccountLinked=true;b.saleAccountId=2;LedgerStore.validate(d);assertEquals(80000,d.balance(d.accounts.get(0)));assertEquals(222000,d.balance(d.accounts.get(1)));assertEquals(0,Ledger.month(d,YearMonth.of(2026,9)).expense);assertEquals(0,Ledger.income(d,2026));String json=LedgerStore.encode(d);LedgerStore.validate(d);assertEquals(json,LedgerStore.encode(d));}
    @Test public void historicalUnlinkedPurchaseNeverChangesBalanceOrExpense(){Ledger.Data d=accounts();Ledger.FundBuy b=buy(fund(d),false);b.at=LocalDateTime.parse("2024-01-05T10:00");b.tradeDate=b.at.toLocalDate();b.confirmDate=b.tradeDate.plusDays(1);LedgerStore.validate(d);assertEquals(300000,d.total());assertEquals(1,d.snapshots.size());}
    @Test public void onlySaleLinkedDoesNotCorrectAnUnlinkedPurchase(){Ledger.Data d=accounts();Ledger.FundBuy b=buy(fund(d),false);b.saleDate=LocalDate.of(2026,9,10);b.saleAt=b.saleDate.atTime(17,0);b.saleAmount=22000;b.saleAccountLinked=true;b.saleAccountId=2;LedgerStore.validate(d);assertEquals(322000,d.total());assertEquals(0,Ledger.month(d,YearMonth.of(2026,9)).expense);}
    @Test public void editsAndDeletionRebuildOnlyOwnedCashCells(){Ledger.Data d=accounts();Ledger.Fund f=fund(d);Ledger.FundBuy b=buy(f,true);LedgerStore.validate(d);assertEquals(80000,d.balance(d.accounts.get(0)));b.amount=30000;LedgerStore.validate(d);assertEquals(70000,d.balance(d.accounts.get(0)));f.buys.clear();d.funds.clear();LedgerStore.validate(d);assertEquals(300000,d.total());assertEquals(1,d.snapshots.size());}
    @Test public void manualBalanceWinsOverAnEditedOldBuy(){Ledger.Data d=accounts();Ledger.FundBuy b=buy(fund(d),true);new AccountCashTest().snap(d,200,"2026-09-06T10:00",1,75000);LedgerStore.validate(d);b.amount=30000;LedgerStore.validate(d);assertEquals(75000,d.balance(d.accounts.get(0)));}
    @Test public void preOpeningLinkedBuyIsRejected(){Ledger.Data d=accounts();Ledger.FundBuy b=buy(fund(d),true);b.at=LocalDateTime.parse("2024-01-05T10:00");try{LedgerStore.validate(d);fail();}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("开户余额"));}}
    @Test public void overdrawnBuyIsRejected(){Ledger.Data d=accounts();Ledger.FundBuy b=buy(fund(d),true);b.amount=100001;try{LedgerStore.validate(d);fail();}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("余额"));}}
    @Test public void sameTimeManualCashBalanceDoesNotDoubleDebit(){Ledger.Data d=accounts();Ledger.FundBuy b=buy(fund(d),true);new AccountCashTest().snap(d,200,"2026-09-05T10:00",1,80000);LedgerStore.validate(d);assertEquals(80000,d.balance(d.accounts.get(0)));assertEquals(0,Ledger.month(d,YearMonth.of(2026,9)).expense);}
    BankLedger.Product bank(Ledger.Data d){BankLedger.Draft draft=new BankLedger.Draft();draft.name="测试银行理财";draft.balance=10000L;draft.at=LocalDateTime.parse("2026-09-05T10:00");return BankLedger.apply(d,0,draft,false,null);}
    @Test public void bankOpeningAndCompletedBuySaleUseLinkedAccounts(){Ledger.Data d=accounts();BankLedger.Product p=bank(d);p.openingAccountLinked=true;p.openingAccountId=1;BankAccounting.flow(d,p,3000,true,LocalDateTime.parse("2026-09-07T10:00"),LocalDateTime.parse("2026-09-07T12:00"));BankLedger.Event e=p.events.get(0);e.accountLinked=true;e.accountId=1;BankAccounting.flow(d,p,2000,false,LocalDateTime.parse("2026-09-08T10:00"),LocalDateTime.parse("2026-09-08T15:00"));e=p.events.get(1);e.accountLinked=true;e.accountId=2;LedgerStore.validate(d);assertEquals(87000,d.balance(d.accounts.get(0)));assertEquals(202000,d.balance(d.accounts.get(1)));assertEquals(0,Ledger.month(d,YearMonth.of(2026,9)).expense);}
    @Test public void pendingBankTradeDoesNotMoveCash(){Ledger.Data d=accounts();BankLedger.Product p=bank(d);BankAccounting.flow(d,p,3000,true,LocalDateTime.parse("2026-09-07T10:00"),null);p.events.get(0).accountLinked=true;p.events.get(0).accountId=1;LedgerStore.validate(d);assertEquals(300000,d.total());}
    @Test public void fullBackupRoundTripsAccountPlanWatchAndBankFields()throws Exception{Ledger.Data d=accounts();Ledger.Fund f=fund(d);Ledger.FundBuy b=buy(f,true);f.plan.enabled=true;f.plan.amount=20000;f.plan.accountId=1;f.plan.startDate="2026-09-01";f.plan.nextDate="2026-10-01";RecurringInvestments.record(d,f,b);BankLedger.Product p=bank(d);p.openingAccountLinked=true;p.openingAccountId=1;Ledger.WatchFund w=new Ledger.WatchFund("006431","测试自选");w.profile.established="2020-01-01";d.watchFunds.add(w);Ledger.WatchGroup g=new Ledger.WatchGroup(300,"债券");g.codes.add(w.code);d.watchGroups.add(g);LedgerStore.validate(d);String json=LedgerStore.encode(d);assertEquals(11,new JSONObject(json).getInt("version"));Ledger.Data restored=LedgerStore.decode(json);LedgerStore.validate(restored);assertEquals(json,LedgerStore.encode(restored));assertTrue(restored.funds.get(0).buys.get(0).buyAccountLinked);assertEquals(1,restored.funds.get(0).plan.records.size());assertTrue(restored.banks.get(0).openingAccountLinked);assertEquals("债券",restored.watchGroups.get(0).name);}
    @Test public void legacyBackupWithoutNewFieldsStaysUnlinked()throws Exception{Ledger.Data d=accounts();buy(fund(d),false);JSONObject root=new JSONObject(LedgerStore.encode(d));root.put("version",10);root.remove("watchFunds");root.remove("watchGroups");JSONObject f=root.getJSONArray("funds").getJSONObject(0);f.remove("plan");JSONObject b=f.getJSONArray("buys").getJSONObject(0);for(String name:new String[]{"buyAccountLinked","buyAccountId","saleAccountLinked","saleAccountId","saleAt"})b.remove(name);Ledger.Data migrated=LedgerStore.decode(root.toString());LedgerStore.validate(migrated);assertEquals(300000,migrated.total());assertFalse(migrated.funds.get(0).plan.enabled);}
    @Test public void weeklyAndMonthlySchedulesHaveStableDates(){Ledger.RecurringPlan p=new Ledger.RecurringPlan();p.frequency="每周";p.dayOfMonth=1;assertEquals(LocalDate.of(2026,10,26),RecurringInvestments.next(p,LocalDate.of(2026,10,25)));p.frequency="每月";p.dayOfMonth=28;assertEquals(LocalDate.of(2026,2,28),RecurringInvestments.next(p,LocalDate.of(2026,1,28)));}
    @Test public void recurringRecordsRequireAccountAndTrackEditedBuy(){Ledger.Data d=accounts();Ledger.Fund f=fund(d);Ledger.FundBuy b=buy(f,false);try{RecurringInvestments.record(d,f,b);fail();}catch(IllegalArgumentException expected){}b.buyAccountLinked=true;b.buyAccountId=1;RecurringInvestments.record(d,f,b);b.amount=25000;RecurringInvestments.reconcile(d);assertEquals(25000,f.plan.records.get(0).amount);f.buys.clear();RecurringInvestments.reconcile(d);assertEquals("买入已删除",f.plan.records.get(0).status);}
    Ledger.WatchFund prices(String...values){Ledger.WatchFund f=new Ledger.WatchFund("000001","测试");LocalDate start=LocalDate.of(2026,1,1);for(int i=0;i<values.length;i++)f.prices.put(start.plusDays(i),new BigDecimal(values[i]));return f;}
    @Test public void incompletePeriodReturnsZeroInsteadOfShorterHistory(){WatchAnalytics.Result r=WatchAnalytics.calculate(prices("1","1.1"),4,LocalDate.of(2026,1,3));assertFalse(r.available);assertEquals(0,r.change,0);}
    @Test public void publishedReturnsIncludeCashDistribution(){Ledger.WatchFund f=prices("1","0.9");f.returns.put(LocalDate.of(2026,1,2),new BigDecimal("1"));WatchAnalytics.Result r=WatchAnalytics.calculate(f,9,LocalDate.of(2026,1,2));assertEquals(1,r.change,.00001);}
    @Test public void maximumDrawdownHasRepairDates(){WatchAnalytics.Result r=WatchAnalytics.calculate(prices("1","1.2","0.9","1.1","1.2"),9,LocalDate.of(2026,1,5));assertEquals(25,r.drawdown,.00001);assertTrue(r.recovered);assertEquals(3,r.recoveryDays);assertEquals(LocalDate.of(2026,1,3),r.troughDate);}
    @Test public void unhealedDrawdownIsExplicit(){WatchAnalytics.Result r=WatchAnalytics.calculate(prices("1","1.2","0.9","1.1"),9,LocalDate.of(2026,1,4));assertFalse(r.recovered);assertEquals(25,r.drawdown,.00001);}
    @Test public void flatPricesHaveFiniteZeroSharpe(){WatchAnalytics.Result r=WatchAnalytics.calculate(prices("1","1","1"),9,LocalDate.of(2026,1,3));assertEquals(0,r.sharpe,0);assertEquals(0,r.drawdown,0);}
    @Test public void lockPeriodUsesCalendarMonthsFromConfirmation(){FundProfile p=new FundProfile();p.inferLock("平安双季鑫6个月持有期债券A");assertEquals(6,p.lockCount);assertEquals(LocalDate.of(2027,4,25),p.unlock(LocalDate.of(2026,10,25)));}
    @Test public void missingProfileIsNotReportedAsZeroFeeOrUnlocked(){FundProfile p=new FundProfile();assertTrue(p.lockLabel().contains("未取得"));assertTrue(p.orUnknown("").contains("暂未取得"));}
    @Test public void publicFeeTablesAndScaleAreParsed(){String overview="成立日期：<span>2024-07-23</span><th>净资产规模</th><td>11.47亿元（截止至：2026年09月30日）<th>份额规模</th>";String fees="管理费率</td><td>0.30%（每年）</td>托管费率</td><td>0.05%（每年）</td>销售服务费率</td><td>0.00%（每年）</td>申购费率</label><table><tr><td>小于100万元</td><td>0.03%</td></tr></table>赎回费率<a name='x'></a></label><table><tr><td>0天以上</td><td>0.00%</td></tr></table>";FundProfile p=FundProfile.parse("6个月持有债",overview,fees);assertEquals("2024-07-23",p.established);assertTrue(p.scale.contains("11.47亿元"));assertTrue(p.buyRules.contains("0.03%"));assertTrue(p.saleRules.contains("0.00%"));assertTrue(p.management.startsWith("0.30%"));}
    @Test public void watchOcrKeepsDigitsInFundNamesAndRejectsNavAsCode(){List<FundRecognition.Line> lines=Arrays.asList(new FundRecognition.Line("平安元利90天持有期债券",20,100,430,130),new FundRecognition.Line("A",20,138,50,165),new FundRecognition.Line("021409",20,180,130,205),new FundRecognition.Line("1.062900",600,150,770,180),new FundRecognition.Line("汇安鼎利纯债债券A",20,250,430,280),new FundRecognition.Line("006431",20,295,130,320));List<WatchOcr.Row> rows=WatchOcr.parse(lines);assertEquals(2,rows.size());assertEquals("平安元利90天持有期债券A",rows.get(0).name);assertEquals("021409",rows.get(0).code);}
    @Test public void duplicateWatchCodesAndReservedGroupsAreRejected(){Ledger.Data d=accounts();d.watchFunds.add(new Ledger.WatchFund("000001","A"));d.watchFunds.add(new Ledger.WatchFund("000001","B"));try{WatchValidation.validate(d);fail();}catch(IllegalArgumentException expected){}d.watchFunds.remove(1);d.watchGroups.add(new Ledger.WatchGroup(1,"全部"));try{WatchValidation.validate(d);fail();}catch(IllegalArgumentException expected){}}
}
